// th15_s7_w06 — TH15 v1.00b Stage 7 (Extra) MainSub04, st07.ecl.txt:1206-1221.
// Dependencies: GirlA03 219-228, GirlA03_at 230-245, GirlA03_at2 247-266.
// Source frame 0 is the MainSub04 entry; the card inserts the 120-frame opening
// buffer before it.  MainLatter re-runs this same formation after the midboss;
// this card is that second, independent instance.

const TIME_LIMIT: int = 2424;      // 120 opening + 2300 window + 4 startup margin
const OPENING_BUFFER: int = 120;
const TH15_RICE: int = 480;        // source type 8, copied from th15/touhou-bullets.ecl

async sub volley(speed: fx) {
    // GirlA03_at2 0250-0264: wait 10, then 10 firing passes.
    wait(10);
    for i in 0..10 {
        sh_reset(0);                       // etNew(0), 0254
        sh_sprite(0, TH15_RICE, 6);        // etSprite(0,8,6), 0256; type 8 -> TH15_RICE
        sh_ring(0, 1);                     // etAim(0,3): fixed-direction full ring
        sh_count(0, 16, 1);                // etCount(0,16,1), 0257
        // etAngle(0,%RANDRAD,0.05235988), 0258. RANDRAD is -pi..pi, i.e. one
        // full BAM turn signed around zero. 3deg is 0.05235988 rad.
        sh_angle(0, (rand(65536) - 32768) as angle, 3deg);
        sh_speed(0, speed, 0fx);           // etSpeed(0,%F0,2.2), 0259; layers=1 uses s0
        // etEx(0,0,2,1,-999999,-999999,-999999), 0260: ANIM type 2 with a=1.
        // Its spawn displacement is position -= 4*velocity; sh_dist reproduces it
        // per bullet. Birth animation/waits themselves are omitted per policy.
        sh_dist(0, 0fx - 4fx * speed);
        sh_fire(0);                        // etOn(0), 0261
        wait(1 + rand(20));                // wait(1 + RAND%20), 0262
    }
}

async sub girl(speed: fx, mirror: int) {
    // GirlA03_at 0232-0239. setHurtbox(24,24) -> r12; setHitbox(16,16) -> r8.
    set_invuln(65535);                     // training shell: keep real enemy alive
    set_hurtbox(12fx);
    set_hitbox(8fx);
    spawn volley(speed);                   // @GirlA03_at2() async, 0234

    var a1: angle = 22.5deg;               // moveVel(0.3926991,3.2), 0235
    var a2: angle = 90deg;                 // moveVelTime(120,1,1.5707964,2.0), 0236
    var a3: angle = -168.75deg;            // moveVelTime(60,4,-2.9452431,4.0), 0238
    if mirror != 0 {
        // enmCreateM child mirror: reflect the x component at each movement
        // write, angle -> pi-angle. The volley base angle is a fresh uniform
        // RANDRAD every pass, so reflecting it would only map that uniform
        // distribution onto itself; no separate mirror branch is needed there.
        a1 = 180deg - a1;
        a2 = 180deg - a2;
        a3 = 180deg - a3;
    }
    move_vel(0, a1, 3.2fx, EASE_LINEAR);
    move_vel(120, a2, 2fx, EASE_QUAD_IN);  // source mode 1 = t^2
    wait(120);
    move_vel(60, a3, 4fx, EASE_QUAD_OUT);  // source mode 4 = 1-(1-t)^2
    loop { wait(1000); }                   // GirlA03_at 0240-0244
}

async sub pattern() {
    wait(OPENING_BUFFER);
    var speed: fx = 1.6fx;                 // %F0 = 1.6f, 1209
    // 40 passes of `if ($A--)` with A=40, 1218-1219.
    for pair in 0..40 {
        // enmCreate("GirlA03", -150 + RANDF2*8, -16, 50, 1000, 1), 1213.
        // RANDF2 is -1..1; this maps it to -8..8. Dropping the source score/item
        // is part of the approved ordinary-drop/invulnerable-shell handling.
        var jl: fx = ((rand(65537) - 32768) as fx) / 4096fx;
        _ = spawn_enemy(-150fx + jl, -16fx, 50, 0, 1000, 0, girl(speed, 0));
        wait(20);
        // enmCreateM(... +150 ...), 1215; child mirror initial bit = 1.
        var jr: fx = ((rand(65537) - 32768) as fx) / 4096fx;
        _ = spawn_enemy(150fx + jr, -16fx, 50, 0, 1000, 0, girl(speed, 1));
        wait(20);
        speed = speed + 0.013fx;           // 1217; children inherit a snapshot
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    kill_all_enemies(KILL_SILENT);         // source wave window ended; tail cleanup
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
